<?php declare(strict_types=1);
$page=max(1,(int)($_GET['page']??1));$result=$application->adminCompanies()->list([], $page,20,$currentUser->id());$counts=$application->adminCompanies()->counts($currentUser->id());$adminContent=static function()use($result,$page,$counts):void{ ?><div class="admin-metrics compact"><article class="admin-metric"><span>Total aprovado</span><strong><?= $counts['mine'] ?></strong></article><article class="admin-metric"><span>Ativas</span><strong><?= $counts['ativo'] ?></strong></article><article class="admin-metric"><span>Vinculadas ao SO</span><strong><?= $counts['so'] ?></strong></article></div><?php if($result['items']===[]):admin_empty('Nenhuma aprovação','Você ainda não aprovou empresas.');else:?><section class="admin-panel"><table class="table os-table"><thead><tr><th>Empresa</th><th>Documento</th><th>Segmento</th><th>Status</th><th>Ação</th></tr></thead><tbody><?php foreach($result['items'] as $company):?><tr><td><?=admin_h($company['nome_fantasia']??$company['razao_social']??'—')?></td><td><?=admin_h($company['documento']??'—')?></td><td><?=admin_h($company['segmento']??'—')?></td><td><?=admin_badge((string)($company['status']??'pendente'))?></td><td><a href="<?=admin_url('empresa.php?id='.(int)$company['id'])?>">Visualizar</a></td></tr><?php endforeach;?></tbody></table><?php admin_pagination($page,$result['total'],20,'minhas-aprovacoes.php');?></section><?php endif;};
